#!/usr/bin/env python3
"""Generate a bounded findings report from saved results; no invented measurements."""
import json,math,hashlib
from catalog import ROOT,CARDS
from combat import fixture,best_attack,mean_damage
OUT=ROOT/'results'
def pct(x):return f'{100*x:.1f}%'
def n(x):return '—' if x is None else f'{x:.2f}'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(map(str,r))+' |' for r in rows])+'\n'
def load(name):return json.loads((OUT/name).read_text())
def main():
 base=load('combat.json');ref=load('refinement.json');advanced=load('advanced.json')+load('healing-timing.json');grappling=load('grappling.json');campaign=load('campaigns.json');builds=load('builds.json');validation=load('combat-validation.json')
 count=sum(r['trials'] for r in base+ref+advanced)+sum(r['reached'] for r in campaign)
 report=['# Working playtest findings','', 'October 11, 2026. Provisional catalog v0.1; no final balance approval implied.','',f'**Retained results:** {len(base)+len(ref)+len(advanced)} isolated configurations, {sum(r["trials"] for r in base+ref+advanced):,} isolated encounters, plus {sum(r["reached"] for r in campaign):,} encounters in 4,000 ten-encounter sequences: **{count:,} encounters total**. Exploratory runs replaced during corrections are not included. There are 38 character snapshots (27 main, 8 alternative advancement, 3 crafting route), {len(CARDS)} provisional purchased/signature cards (including 81 signature options), and 11 universal references. An additional 240,000 local grappling trials are reported separately from encounters.','', '## Main finding','', 'The rebuilt rules can produce roughly four-round encounters with the proposed higher ordinary damage. However, damage alone has not brought both healing and non-healing parties into the desired wound ranges in a robust way. Armor, enemy targeting, and support access matter at least as much as the headline damage profile.','', 'The best useful anchor below matches the no-healer goal and duration, but healing is more protective than the suggested 5–15% wound goal. These were explicitly soft goals; the correct response is to show that trade-off, not force a target by assuming poor healing decisions.','']
 anchor=[r for r in ref if r['group']=='refinement' and r['ehp']==14 and r['damage']==[5,6,8] and r['target']=='spread' and r.get('threshold')==.5]
 report+=['## Candidate ordinary encounter anchor','','Four enemies, each HP 14, physical resistance 1, damage 5/6/8; spread targeting. Four actual level-1 builds, spare-Maneuver Defend, owned shields, no potions. Player Novice attacks use the working catalog, generally 4/5/7. These are test fixtures, not an approved bestiary.', '',table(['Healing policy','Mean rounds','Any party wound','Mean wounds','Mean healing actions','Win'],[(r['policy'],n(r['rounds']),pct(r['any_wound']),n(r['wounds']),n(r['heals']),pct(r['win'])) for r in anchor]),'At 3,000 trials each, zero observed events does not mean impossible. Worst-case 95% sampling margin is about ±1.8 percentage points; model omissions are larger.','']
 report+=['## Ordinary damage and resistance','','New ordinary attacks keep Weak damage meaningful, and stronger results can add movement or other effects. The baseline omits those riders, so its duration measures raw-damage contribution only. The proposed 2/3/5 basic attack deals 2 on Strong against resistance 3; resistance 4+ still flattens it. That scope remains a designer decision.','',table(['Novice profile','No-healer rounds','No-healer wound','Healer rounds','Healer wound'],[(p,n(next(r['rounds'] for r in base if r['group']=='damage' and r['ehp']==12 and r['damage']==[4,5,7] and r['target']=='focus' and r['profile']==p and r['policy']=='none')),pct(next(r['any_wound'] for r in base if r['group']=='damage' and r['ehp']==12 and r['damage']==[4,5,7] and r['target']=='focus' and r['profile']==p and r['policy']=='none')),n(next(r['rounds'] for r in base if r['group']=='damage' and r['ehp']==12 and r['damage']==[4,5,7] and r['target']=='focus' and r['profile']==p and r['policy']=='one')),pct(next(r['any_wound'] for r in base if r['group']=='damage' and r['ehp']==12 and r['damage']==[4,5,7] and r['target']=='focus' and r['profile']==p and r['policy']=='one'))) for p in ['old','flat','new','high']]),'Profiles are old 2/4/6, flat 4/4/6, new per-card (usually 4/5/7), high 5/6/8. All other fixture inputs in this table are fixed. These focus-fire cases deliberately expose fragility; they are not the ordinary anchor above.','']
 report+=['## Targeting and preparation','','Same HP-12, damage-4/5/7 enemies can create radically different pressure. Mixed targeting chooses the lowest-current-HP PC with the listed probability, otherwise a random upright PC. It is an experiment, not a creature intelligence rule.','',table(['Target policy','Healing','Rounds','Any wound'],[(r['target']+(' '+str(r['focus_chance']) if 'focus_chance' in r else ''),r['policy'],n(r['rounds']),pct(r['any_wound'])) for r in ref if r['group']=='refinement' and r['ehp']==12 and r['damage']==[4,5,7] and r.get('threshold',.5)==.5]),'A real board can protect weaker characters through reach and occupied squares. The range-free model cannot price that protection. Do not set CV assuming every enemy always reaches the weakest PC, or assuming enemies always spread harmlessly.','']
 report+=['## Added mechanics: controlled layers','','Each layer changes one rule against the same HP-12, damage-4/5/7 focus-fire reference. “One healer” always uses the same actual learned Mend card. Contact assumptions and omitted counter-actions are in [test contract](../tests/README.md).','',table(['Layer','Healing','Rounds','Any wound','Timeout'],[(r['layer'],r['policy'],n(r['rounds']),pct(r['any_wound']),pct(r['timeout'])) for r in base if r['group']=='layer']), 'Opportunity damage raises the cost of casting in contact; Strong interruption raises it further. It is not established as necessary. The party may instead Disengage and move before casting, which this contact stress case does not simulate. Burning results assume the party does not spend Main Actions extinguishing during combat.','', 'Enemy healing uses the same half/full/full restoration rather than a weaker NPC-only rule. Multiple enemy healers can still prolong fights and create timeouts. The NPC-death-at-0 rule makes finishing targets an important difference from player recovery.','']
 report+=['## Creation and progression','','See [complete build summaries](creation.md) and the ordered ledgers in builds.json. All nine classes have legal level-1/3/7 examples. Requirements do not depend on legacy content. The fixed attribute sum gives 1,246 legal labeled arrays; each two-attribute minimum admits 678. That does not establish equal class appeal.','', '- The accepted mental adjustment gives 7–16 DP at each creation stage: an 18-DP spread across both stages. Physical-heavy and mental-heavy builds now have a real development trade-off.','- The low-Brawn Arcanist has capacity 4. Tools and later acquisitions can cause encumbrance; no item or backpack is exempted to hide this. Players can choose what to carry rather than being forced to carry everything granted.','- Automatic grant deduplication works: compatible attack cards use one 1-Bulk weapon. Crafting grants tools and two provisional ordinary recipes; ingredients remain explicit.','- The working catalog is still small. Large level-7 DP banks reflect a lack of attractive tested purchases as well as deliberate restraint; they do not prove the 8 + level award is too large.','- Most later example builds can afford Mend. Test all-healer parties, because healing access is a build choice rather than a class monopoly.','- Higher-tier signature prototypes now have distinct class-specific effects. Their tactical impact has not been simulated, so these results do not establish full class balance. The following combat table disables signatures and non-damage riders.','',table(['Level','Healing policy','Rounds','Any wound','Healing actions'],[(r['level'],r['policy'],n(r['rounds']),pct(r['any_wound']),n(r['heals'])) for r in ref if r['group']=='healer_access']), 'This comparison holds enemies at HP 16 and damage 5/6/8. It measures growing offense against the same threat; it is not a recommendation to keep all encounters unchanged as characters advance.','']
 report+=['## Attrition','','Ten sequential candidate-anchor encounters, full HP breaths, persistent scars/Grit, stop at first terminal PC or failure. Active wound penalties are omitted, so these results understate long-term adversity. Potions are separate supplied d4 bottles; replenishment is explicit.','',table(['Healing','Potions','Resupply','Encounter','Full-party completion','Grit left among reached','Scars among reached'],[(r['policy'],r['potions'],r['resupply'],r['encounter'],pct(r['full_party_completion']),n(r['mean_grit_remaining']),n(r['mean_scars'])) for r in campaign if r['encounter'] in [1,5,10]]),'No refill of Grit is assumed. A fresh-party encounter rate and survival through ten encounters answer different questions. This campaign sample does not certify the provisional wound table.','']
 report+=['## Longer-duration anchors and high-HP healing','','These are nearest tested duration matches, not certified difficulty labels. HP, resistance and count alone do not establish hard or extreme difficulty. Fresh level-3/7 characters have their full granted/purchased Grit; they are not assumed campaign survivors with unspent Grit.', '',table(['Level','Target rounds','Enemy count × HP','Resistance','Observed rounds','Any wound','Any terminal PC'],[(level,target,str(r['count'])+' × '+str(r['ehp']),r['eres'],n(r['rounds']),pct(r['any_wound']),pct(r['any_terminal'])) for level in (1,3,7) for target in (4,6,10) for r in [min([x for x in base+advanced if x['level']==level and x['policy']=='one' and x.get('composition')=='mixed' and x['profile']=='new' and x.get('group') in ['bodies','progression','duration_anchor']],key=lambda x:abs(x['rounds']-target))]]),'',table(['Level','Solo HP','Healing policy','Rounds','Timeout'],[(r['level'],r['ehp'],r['policy'],n(r['rounds']),pct(r['timeout'])) for r in advanced if r['group']=='solo_healing' and r['policy']=='one']),'Full-HP restoration on a high-HP creature can still defeat ordinary damage throughput. Counterplay and encounter role must be tested; do not quietly give the creature a different healing formula.','', '## Typed resistance','','The following holds physical resistance at 3 while adding fire resistance. Players select among attacks they actually learned. No unowned damage-type switch is assumed.', '',table(['Level','Fire resistance','Rounds','Any wound'],[(r['level'],r['fire_res'],n(r['rounds']),pct(r['any_wound'])) for r in advanced if r['group']=='typed_resistance' and r['policy']=='one']),'Magic looking strong against physical-only armor is not evidence of general superiority against all defenses. Creature cards need explicit typed resistance and observable clues.','', '## Alternating-turn grappling experiment','','Local three-round contest, no allies helping the target, continuous contact, neutral Brawn 0 on both sides. Target always chooses Main and uses Force when available; removal reduces oldest contributions first (provisional bookkeeping). Movement after a successful escape is deliberately excluded, making this a contact-pressure test. No narrative critical/fumble riders.', '',table(['Grapplers','First side','Restrained round 1','Restrained by round 3'],[(r['grapplers'],r['first'],pct(r['restrained_round1']),pct(r['restrained_by_round3'])) for r in grappling if r['attack_attribute']==0 and r['force_attribute']==0]),'An intervening Force attempt matters substantially in the first round, but sustained multiple-grappler pressure dominates if the target remains in reach. This supports testing escape movement and ally intervention on a board rather than changing the agreed rating-3 restriction blindly.','', '## Alternative investments and crafting entry','','[Alternative spending plans](variants.md) show eight additional snapshots. A durability-focused Protector reaches 31 HP at level 7 through six paid HP increases rather than automatic level growth. More banked DP in specialist routes reinforces the need for a richer tested catalog before drawing a final DP-budget conclusion.', '', 'The [crafting entry route](../crafting.md) pairs Frontier Forest Forage with Apprentice Field Craft. Its three snapshots have actual tools, recipes and material-gathering permission, so crafting can function in a suitable environment without an assumed free supply kit. Physical HP healing also has a provisional Field Dressing card; it is not part of the Mend-only combat comparisons.','']
 report+=['## Healing policy sensitivity: the surprising boss result','','The level-7 party sometimes took longer than the level-3 party against the same self-healer. Saved turn traces show why: crossing the half-HP trigger more consistently can make the enemy heal every turn, while a lower-damage sequence sometimes leaves it just above the trigger and earns another attack window. This is a property of the chosen policy and turn timing, not a general claim that weaker attacks are better.', '',table(['Party level','Enemy heals at HP fraction','Mean rounds','Timeout'],[(r['level'],r['enemy_threshold'],n(r['rounds']),pct(r['timeout'])) for r in advanced if r['group']=='healing_timing']),'At level 1 the same HP-48 enemy changes from almost no timeouts at the quarter-HP trigger to all timeouts at the half-HP trigger. This is strong evidence that encounter results cannot be separated from healing policy. [Saved traces](boss-traces.json) retain complete turn HP histories for seed 12 at levels 1/3/7. These are illustrative traces; percentages come from 3,000 encounters per configuration.','']
 # Explicit metric experiment with held-out body counts.


 party=fixture();dref=sum(best_attack(b,1)[0] for b in party)/4
 tref=sum(mean_damage([4,5,7],b['attrs']['Agility'],1+int('shield' in b['gear']),b['resistance'],True) for b in party)/4
 cv=[]
 for r in base:
  if r['group']!='bodies' or r['policy']!='none':continue
  outgoing=sum(best_attack(b,r['eres'])[0] for b in party)/4
  incoming=sum(mean_damage(r['damage'],b['attrs']['Agility'],1+int('shield' in b['gear']),b['resistance'],True) for b in party)/4
  score=10*(r['ehp']/outgoing)/(12/dref)*(incoming/tref)*r['count']
  cv.append(dict(id=r['id'],count=r['count'],hp=r['ehp'],cv=score,rounds=r['rounds'],wound=r['any_wound'],split='train' if r['count'] in [2,4,8] else 'holdout'))
 train=[r for r in cv if r['split']=='train'];test=[r for r in cv if r['split']=='holdout'];slope=sum(r['cv']*r['rounds'] for r in train)/sum(r['cv']**2 for r in train)
 for r in cv:r['predicted_rounds']=slope*r['cv'];r['absolute_error']=abs(r['predicted_rounds']-r['rounds'])
 mae=sum(r['absolute_error'] for r in test)/len(test)
 pressure=[]
 body_rows=[r for r in base if r['group']=='bodies' and r['policy']=='none']
 for adjusted in (False,True):
  def score(r):return r['count']*r['ehp']*((r['count']+1)/5 if adjusted else 1)
  tr=[r for r in body_rows if r['count'] in (2,4,8)];te=[r for r in body_rows if r['count'] in (3,6)]
  coefficient=sum(score(r)*r['enemy_attacks'] for r in tr)/sum(score(r)**2 for r in tr)
  error=sum(abs(score(r)*coefficient-r['enemy_attacks']) for r in te)/len(te)
  pressure.append(dict(count_adjusted=adjusted,coefficient=coefficient,holdout_mae_enemy_attacks=error))
 (OUT/'cv.json').write_text(json.dumps(dict(reference_cv=10,rounds_per_cv=slope,holdout_mae_rounds=mae,pressure_models=pressure,rows=cv),indent=2)+'\n')
 report+=['## A better first pressure estimate','',f'For the same body-count fixtures, multiplying the summed durability score by **(enemy count + 1) / 5** reduces held-out error in predicted enemy attack opportunities from **{pressure[0]["holdout_mae_enemy_attacks"]:.2f} to {pressure[1]["holdout_mae_enemy_attacks"]:.2f} attacks**. Four enemies give multiplier 1. This reflects the additional turns available while several bodies remain alive.', '', 'This is a measured lead for the CV algorithm, not an adopted encounter multiplier. It was tested only on these ordinary level-1 bodies with the same damage and resistance. Keep duration and pressure as separate estimates; damage types, healing, control, body blocking and party size still require calibration.','']

 report+=['## Combat Value: useful structure, not yet a reliable budget','',f'The provisional durability × threat metric normalizes a reference Skirmisher to CV 10. A linear duration fit trained on counts 2/4/8 and held out counts 3/6 has mean absolute duration error **{mae:.2f} rounds** on those held-out configurations. This is a narrow internal check, not broad validation. It does not predict wound probability, healing loops, AoE, or control.', '',table(['Count × HP','Total CV','Observed rounds','Predicted rounds','Any wound','Split'],[(str(r['count'])+' × '+str(r['hp']),n(r['cv']),n(r['rounds']),n(r['predicted_rounds']),pct(r['wound']),r['split']) for r in cv]), 'Recommendation: retain separate durability, offensive pressure, body count, and special-ability notes alongside any scalar CV. Do not publish hard/very-hard thresholds from this formula yet. Next calibrations should use several party compositions and board layouts, then select encounter anchors at roughly 4/6/10 rounds with acceptable wound rates.','']
 report+=['## Priority findings for Bruce','','1. **Healing trade-off:** the four-round candidate without healing is near the wound goal; with healing it is safer than the soft goal. Decide whether that is acceptable before adding a universal interruption rule.','2. **Preparation and formation:** armor and access to the weakest PC change the result dramatically. The next physical playtest needs a declared map, starting positions, equipment and potions.','3. **Summon bodies:** unlimited summons plus immediate activation can create fresh blockers every turn and preload a battlefield. Command limits alone do not address that. Preserve unlimited summons while testing duration, placement and fragility.','4. **Control concentration:** multiple grapplers can restrain very reliably without each grappler becoming equally restricted. Test an escape opportunity between applications and a rescued ally, not only a static probability.','5. **Basic damage scope:** Strong 5 achieves 2 damage against resistance 3, not higher resistance. Decide whether that is the intended low-tier boundary.','6. **Catalog quality:** test the higher signatures and expand meaningful high-level utility before reducing DP awards. Starter recipe count remains a provisional two.','7. **Wound detail:** the compact physical/mental table is an explicit proposed replacement. Active penalties need a separate campaign test before assessing lifetime survivability.','', '## What is and is not completed','','The independent working set, creation ledgers, revised-damage sweeps, incremental mechanic checks, advancement fixtures, and first CV experiment are complete for this pass. They tackle steps 1–7 without asserting the game is now balanced. Full map-based tactics, high-level signature balance, broad party-size validation, and a reliable final CV budget remain further iterations. Layout and book construction have not been started.','', 'For individual advanced-mechanic examples, see [tactical cases](tactical-cases.md). For assumptions and reproduction, see [test contract](../tests/README.md).','']
 (OUT/'findings.md').write_text('\n'.join(report))
 (OUT/'manifest.json').write_text(json.dumps(dict(isolated_configurations=len(base)+len(ref)+len(advanced),isolated_encounters=sum(r['trials'] for r in base+ref+advanced),campaign_sequences=4000,campaign_encounters=sum(r['reached'] for r in campaign),total_encounters=count,build_snapshots=len(builds)+len(load('variants.json'))+len(load('craft-route.json')),local_grappling_trials=sum(r['trials'] for r in grappling),catalog_cards=len(CARDS),combat_checks=validation['checks'],input_sha256={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(list(ROOT.glob('*.md'))+[ROOT/'catalog.json']+list((ROOT/'tests').glob('*.py')))}),indent=2)+'\n')
 print(json.dumps(dict(total_encounters=count,cv_holdout_mae_rounds=mae)))
if __name__=='__main__':main()
